```tsx
import { useId } from "react";
import "./ChipFilter.css";

export interface ChipOption<T extends string> {
  value: T;
  label: string;
}

export interface ChipFilterProps<T extends string> {
  label: string;
  options: readonly ChipOption<T>[];
  selected: readonly T[];
  onToggle: (value: T) => void;
}

export function ChipFilter<T extends string>({
  label,
  options,
  selected,
  onToggle,
}: ChipFilterProps<T>) {
  const labelId = useId();

  return (
    <div role="group" aria-labelledby={labelId} className="chip-filter">
      <span id={labelId} className="chip-filter-label">
        {label}
      </span>
      <div className="chip-filter-options">
        {options.map((option) => {
          const isOn = selected.includes(option.value);
          return (
            <button
              key={option.value}
              type="button"
              className="chip"
              aria-pressed={isOn}
              onClick={() => onToggle(option.value)}
            >
              <span className="chip-mark" aria-hidden="true">
                {isOn ? "✓" : ""}
              </span>
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
```

